1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { isNavigable, seaMap, SIGHT_RADIUS_TILES } from "@pirate-sea-race/content";
3	import { DuelMessageType, INPUT_HOLD_FRAMES } from "@pirate-sea-race/protocol";
4	import { DUEL_RESULT_TICKS, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
5	import { createEncounterConfig, encounterRules } from "@pirate-sea-race/simulation/encounters";
6	import { MAX_INPUT_DELAY, MIN_INPUT_DELAY } from "@pirate-sea-race/simulation/netcode";
7	import { duelInput, hashState } from "@pirate-sea-race/simulation/duel";
8	import { AHEAD, ImpairmentProxy, replayRecordedDuel, sleep, type HeadlessClient } from "@pirate-sea-race/test-tools";
9	import { appliedPairs } from "./harness.js";
10	import {
11	  brawler,
12	  resultOf,
13	  tracker,
14	  containsText,
15	  EAST,
16	  grapple,
17	  HUB_X,
18	  lobbyOf,
19	  NORTH,
20	  OPEN_ROW,
21	  openWater,
22	  pairInRange,
23	  playersAt,
24	  recordSightings,
25	  roomOf,
26	  SOUTH,
27	  TILE,
28	  WEST,
29	} from "./seaDuelSetup.js";
30	
31	/**
32	 * Duels at sea (§6, §14): the grapple's telegraph and escape, the duel inside the match room, the return, and §12
33	 * inside the match room: a fighter who drops keeps the seat for ten seconds while the fight goes on with their input
34	 * substituted (neutral after 250 ms); back in time they resume the same fight, otherwise they forfeit. A quit forfeits
35	 * at once; both gone on the same frame cancels. And §6's ready check: a fighter not ready ten seconds after the grapple
36	 * forfeits, both not ready cancels, and a late one delays the fight. Each test plays its own match; they run at once.
37	 * (The draw, whose mirrored inputs want a quiet machine, is in `seaDuelHarness.test.ts`.)
38	 */
39	let server: RunningGameServer;
40	let endpoint: string;
41	const rules = createEncounterConfig();
42	const { grapple: grappleRules } = encounterRules;
43	
44	beforeAll(async () => {
45	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true });
46	  endpoint = `http://127.0.0.1:${server.port}`;
47	});
48	
49	afterAll(async () => {
50	  await server.close();
51	});
52	
53	describe.concurrent("the grapple (§6 at sea)", () => {
54	  it("telegraphs a one-second windup to both players, then reserves both ships, which stop and ignore sailing", async ({ onTestFinished }) => {
55	    const track = tracker(onTestFinished);
56	    const { host, guest } = await pairInRange(endpoint, track);
57	    const start = { host: host.ship()!, guest: guest.ship()! };
58	    host.tapGrapple();
59	    // The attacker sees its aim; the target sees the grapple aimed at it, from the attacker's side.
60	    await host.waitFor(() => host.grapples().length === 1, 2000);
61	    await guest.waitFor(() => guest.grapples().length === 1, 2000);
62	    const telegraph = host.grapples()[0]!;
63	    expect(telegraph).toMatchObject({ attackerId: host.sessionId, defenderId: guest.sessionId, aim: EAST });
64	    expect(telegraph.landTick - telegraph.startTick).toBe(grappleRules.windupTicks);
65	    expect(guest.grapples()).toEqual([telegraph]);
66	
67	    for (const client of [host, guest]) await client.waitFor(() => client.status()?.mode === "duel", 3000);
68	    expect(host.grapples()).toEqual([]);
69	    expect(lobbyOf(host)).toMatchObject({ phase: "countdown" });
70	    expect(host.fighter.slot).toBe(0);
71	    expect(guest.fighter.slot).toBe(1);
72	    // Both ships are held where the grapple landed: full ahead does nothing.
73	    await Promise.all([host.hold(AHEAD, 600), guest.hold(AHEAD, 600)]);
74	    expect(host.ship()).toMatchObject({ x: start.host.x, y: start.host.y, speed: 0 });
75	    expect(guest.ship()).toMatchObject({ x: start.guest.x, y: start.guest.y, speed: 0 });
76	    // A fighter's own ship stays in its view; the other's, and every grapple and marker, are out of it.
77	    expect(host.visibleShipIds()).toEqual([host.sessionId]);
78	    expect(guest.visibleShipIds()).toEqual([guest.sessionId]);
79	    expect(roomOf(host).refusedDuelReports).toBe(0);
80	  });
81	
82	  it("lets a target that sails out of range during the windup escape, and starts the attacker's cooldown", async ({ onTestFinished }) => {
83	    const track = tracker(onTestFinished);
84	    const { host, guest } = await pairInRange(endpoint, track, { guestHeading: EAST });
85	    expect(openWater({ tileX: HUB_X + 3, tileY: OPEN_ROW, heading: EAST }, { tileX: HUB_X + 9, tileY: OPEN_ROW, heading: EAST })).toBe(true);
86	    host.tapGrapple();
87	    await guest.waitFor(() => guest.grapples().length === 1, 2000);
88	    const { landTick } = guest.grapples()[0]!;
89	    // The guest runs east, away: in a second under sail it makes two tiles, out of the six-tile range.
90	    await guest.holdUntil(AHEAD, () => host.worldTick > landTick + 2, 4000);
91	    await host.waitFor(() => host.grapples().length === 0 && (host.status()?.cooldownUntil ?? 0) > 0, 2000);
92	    expect(host.status()).toMatchObject({ mode: "sea", cooldownUntil: landTick + grappleRules.missCooldownTicks });
93	    expect(guest.status()).toMatchObject({ mode: "sea" });
94	    expect(host.duelCount + guest.duelCount).toBe(0);
95	    // In cooldown, J does nothing, even with the guest back in range and in front.
96	    await guest.placeShip(endpoint, { tileX: HUB_X + 3, tileY: OPEN_ROW, heading: WEST });
97	    host.tapGrapple();
98	    await sleep(400);
99	    expect(host.grapples()).toEqual([]);
100	  });
101	
102	  it("lets a target that sails out of the aim during the windup escape", async ({ onTestFinished }) => {
103	    const track = tracker(onTestFinished);
104	    // Three tiles apart, the guest heading south: in the second of windup it moves two tiles, 35° off the aim.
105	    const seats = [
106	      { tileX: HUB_X - 1, tileY: OPEN_ROW, heading: EAST },
107	      { tileX: HUB_X + 2, tileY: OPEN_ROW, heading: SOUTH },
108	    ];
109	    expect(openWater(seats[1]!, { ...seats[1]!, tileY: OPEN_ROW + 3 })).toBe(true);
110	    const [host, guest] = (await playersAt(endpoint, seats, track)) as [HeadlessClient, HeadlessClient];
111	    await host.waitFor(() => host.ship(guest.sessionId) !== undefined);
112	    host.tapGrapple();
113	    await guest.waitFor(() => guest.grapples().length === 1, 2000);
114	    const { landTick } = guest.grapples()[0]!;
115	    await guest.holdUntil(AHEAD, () => host.worldTick > landTick + 2, 4000);
116	    await host.waitFor(() => (host.status()?.cooldownUntil ?? 0) > 0, 2000);
117	    const off = guest.ship()!;
118	    const onShip = host.ship()!;
119	    // Still in range, but outside ±22.5° of the aim.
120	    expect(Math.hypot(off.x - onShip.x, off.y - onShip.y)).toBeLessThan(grappleRules.rangeTiles * TILE);
121	    expect((Math.atan2(off.y - onShip.y, off.x - onShip.x) * 180) / Math.PI).toBeGreaterThan(22.5);
122	    expect(host.status()).toMatchObject({ mode: "sea", cooldownUntil: landTick + grappleRules.missCooldownTicks });
123	    expect(guest.status()?.mode).toBe("sea");
124	  });
125	
126	  it("does nothing, and costs nothing, when J is pressed with nobody in range and in front", async ({ onTestFinished }) => {
127	    const track = tracker(onTestFinished);
128	    // One player out of range ahead, one in range but behind the attacker.
129	    const seats = [
130	      { tileX: HUB_X, tileY: OPEN_ROW, heading: EAST },
131	      { tileX: HUB_X + 8, tileY: OPEN_ROW, heading: WEST },
132	      { tileX: HUB_X - 3, tileY: OPEN_ROW, heading: EAST },
133	    ];
134	    const [host, ahead, behind] = (await playersAt(endpoint, seats, track)) as [HeadlessClient, HeadlessClient, HeadlessClient];
135	    const sightings = [host, ahead, behind].map(recordSightings);
136	    for (let press = 0; press < 3; press++) {
137	      host.tapGrapple();
138	      await sleep(300);
139	    }
140	    await sleep(600);
141	    for (const seen of sightings) expect(seen.grapples.size).toBe(0);
142	    expect(host.status()).toMatchObject({ mode: "sea", cooldownUntil: 0 });
143	    expect(roomOf(host).encounterState.attempts).toEqual([]);
144	  });
145	
146	  it("never grapples a protected target: a duel's winner, until the protection runs out", async ({ onTestFinished }) => {
147	    const track = tracker(onTestFinished);
148	    // Host west, guest east (the duel), and a third player four tiles south of the host, facing north at it.
149	    const seats = [
150	      { tileX: HUB_X - 3, tileY: OPEN_ROW, heading: EAST },
151	      { tileX: HUB_X + 3, tileY: OPEN_ROW, heading: WEST },
152	      { tileX: HUB_X - 3, tileY: OPEN_ROW + 4, heading: NORTH },
153	    ];
154	    for (let tileY = OPEN_ROW; tileY <= OPEN_ROW + 4; tileY++) expect(isNavigable(seaMap, HUB_X - 3, tileY)).toBe(true);
155	    const [host, guest, third] = (await playersAt(endpoint, seats, track)) as [HeadlessClient, HeadlessClient, HeadlessClient];
156	    await grapple(host, guest);
157	    // The guest quits: the host wins at once by forfeit and sails on with the winner's protection.
158	    await guest.leave();
159	    await host.waitFor(() => host.status()?.protection === "win", 3000);
160	    const { protectedUntil } = host.status()!;
161	    const sightings = recordSightings(third);
162	    third.tapGrapple();
163	    await sleep(500);
164	    expect(sightings.grapples.size).toBe(0);
165	    expect(third.status()).toMatchObject({ mode: "sea", cooldownUntil: 0 });
166	    // Once the eight seconds are over, the same press starts a grapple.
167	    await third.waitFor(() => third.worldTick > protectedUntil + 1, 12_000);
168	    expect(host.status()).toMatchObject({ protection: "", protectedUntil: 0 });
169	    third.tapGrapple();
170	    await third.waitFor(() => third.grapples().some((each) => each.defenderId === host.sessionId), 2000);
171	  }, 30_000);
172	});
173	
174	describe.concurrent("the duel inside the match room", () => {
175	  it("counts down three seconds, measures the round trip, then fights over the standalone duel's netcode to a KO", async ({ onTestFinished }) => {
176	    const track = tracker(onTestFinished);
177	    const { host, guest } = await pairInRange(endpoint, track);
178	    const reservedAt = Date.now();
179	    await grapple(host, guest);
180	    await host.waitFor(() => host.fighter.phase === "fighting", 5000);
181	    expect(Date.now() - reservedAt).toBeGreaterThanOrEqual(2700);
182	    const room = roomOf(host);
183	    const diagnostics = room.seaDuelDiagnostics(host.sessionId)!;
184	    // The shared input delay, chosen from 20-odd probes of each fighter, within §15's 3 to 8 frames (locally near 3;
185	    // the tests of this file run at once, so the exact value is not pinned).
186	    expect(diagnostics.inputDelay).toBeGreaterThanOrEqual(MIN_INPUT_DELAY);
187	    expect(diagnostics.inputDelay).toBeLessThanOrEqual(MAX_INPUT_DELAY);
188	    expect(guest.fighter.lobby?.inputDelay).toBe(diagnostics.inputDelay);
189	    expect(diagnostics.rttSamples["0"]!.length).toBeGreaterThanOrEqual(20);
190	    expect(diagnostics.rttSamples["1"]!.length).toBeGreaterThanOrEqual(20);
191	
192	    host.fighter.play(brawler(0));
193	    const result = await resultOf(host, guest);
194	    expect(result).toEqual({ phase: "over", winner: 0, reason: "ko" });
195	    for (const client of [host, guest]) {
196	      expect(client.fighter.bundles[0]).toMatchObject({ frame: 0, inputs: [] });
197	      expect(client.fighter.stats).toMatchObject({ desyncs: 0 });
198	      expect(client.fighter.stats!.hashChecks).toBeGreaterThanOrEqual(100);
199	      expect(client.fighter.confirmedState?.result).toMatchObject({ winner: 0, reason: "ko" });
200	    }
201	    expect(room.seaDuelDiagnostics(host.sessionId)!.dropped["0"]).toMatchObject({ "rate-limited": 0, "future-frame": 0 });
202	  }, 30_000);
203	
204	  it("shows a third player in sight the duel marker but no duel messages, and one out of sight neither; both keep sailing", async ({ onTestFinished }) => {
205	    const track = tracker(onTestFinished);
206	    // The fight between the hub's -3 and +3 tiles; a watcher 4 tiles south of the hub (in sight of the marker) and a
207	    // stranger 12 tiles further east (out of sight of everything).
208	    const seats = [
209	      { tileX: HUB_X - 3, tileY: OPEN_ROW, heading: EAST },
210	      { tileX: HUB_X + 3, tileY: OPEN_ROW, heading: WEST },
211	      { tileX: HUB_X - 6, tileY: OPEN_ROW + 4, heading: EAST },
212	      { tileX: HUB_X + 3 + SIGHT_RADIUS_TILES + 2, tileY: OPEN_ROW, heading: EAST },
213	    ];
214	    const [host, guest, watcher, stranger] = (await playersAt(endpoint, seats, track)) as HeadlessClient[] as [HeadlessClient, HeadlessClient, HeadlessClient, HeadlessClient];
215	    await watcher.waitFor(() => watcher.ship(host.sessionId) !== undefined && watcher.ship(guest.sessionId) !== undefined);
216	    const seen = { watcher: recordSightings(watcher), stranger: recordSightings(stranger) };
217	    const marks = { watcher: watcher.frameCount, stranger: stranger.frameCount };
218	    await grapple(host, guest);
219	    await host.waitFor(() => host.fighter.phase === "fighting", 5000);
220	    // The watcher saw the telegraph and sees the marker where the fight is, and no fighter's ship any more.
221	    expect([...seen.watcher.grapples]).toEqual([`${host.sessionId}>${guest.sessionId}`]);
222	    await watcher.waitFor(() => watcher.markers().length === 1);
223	    const [marker] = watcher.markers();
224	    expect(marker).toMatchObject({ x: HUB_X * TILE + TILE / 2, y: OPEN_ROW * TILE + TILE / 2 });
225	    expect(watcher.visibleShipIds()).toEqual([watcher.sessionId]);
226	    // The world goes on: the watcher sails during the fight.
227	    const before = watcher.ship()!;
228	    await watcher.hold(AHEAD, 800);
229	    await watcher.waitFor(() => watcher.ship()!.x > before.x);
230	    await host.fighter.waitForConfirmed(60);
231	
232	    // Neither onlooker got the duel's lobby or any of its messages; the stranger saw no telegraph and no marker.
233	    for (const [name, client] of [["watcher", watcher], ["stranger", stranger]] as const) {
234	      expect(seen[name].duelLobbies, name).toBe(0);
235	      const frames = client.framesSince(marks[name]);
236	      expect(frames.length).toBeGreaterThan(0);
237	      for (const type of [DuelMessageType.Frames, DuelMessageType.Probe]) expect(frames.some((frame) => containsText(frame, type)), `${name} ${type}`).toBe(false);
238	    }
239	    expect(seen.stranger.grapples.size).toBe(0);
240	    expect(seen.stranger.markers).toBe(0);
241	    // The fighters did get them.
242	    expect(host.framesSince(0).some((frame) => containsText(frame, DuelMessageType.Frames))).toBe(true);
243	
244	    // The duel ends (the guest quits): the marker goes.
245	    await guest.leave();
246	    await watcher.waitFor(() => watcher.markers().length === 0, 3000);
247	    await watcher.waitFor(() => watcher.ship(host.sessionId) !== undefined, 3000);
248	  }, 30_000);
249	});
250	
251	describe.concurrent("the return to the world (§6)", () => {
252	  it("returns the winner to its encounter position with 8 s of protection, and respawns the loser at the rules' dock 15 s after the end with 20 s", async ({ onTestFinished }) => {
253	    const track = tracker(onTestFinished);
254	    const { host, guest } = await pairInRange(endpoint, track);
255	    const at = { host: host.ship()!, guest: guest.ship()! };
256	    await grapple(host, guest);
257	    host.fighter.play(brawler(0));
258	    expect(await resultOf(host, guest)).toMatchObject({ winner: 0, reason: "ko" });
259	    const room = roomOf(host);
260	
261	    // The same tick: the winner is back where it was with protection, the loser waits out of the world.
262	    await host.waitFor(() => host.status()?.protection === "win", 2000);
263	    await guest.waitFor(() => guest.status()?.mode === "respawning", 2000);
264	    const settled = host.status()!.protectedUntil - encounterRules.winProtectionTicks;
265	    expect(guest.status()!.respawnAt).toBe(settled + encounterRules.respawnDelayTicks);
266	    expect(host.status()!.mode).toBe("sea");
267	    expect(host.ship()).toMatchObject({ x: at.host.x, y: at.host.y, speed: 0 });
268	    // The loser's ship is gone from every view, its own included; the result stays in the lobby for a moment.
269	    await host.waitFor(() => host.ship(guest.sessionId) === undefined);
270	    expect(guest.ship()).toBeUndefined();
271	    expect(room.viewedShipIds(host.sessionId)).toEqual([host.sessionId]);
272	    await host.waitFor(() => host.duelCount === 0, 5000);
273	    expect(host.worldTick).toBeGreaterThan(settled + DUEL_RESULT_TICKS);
274	
275	    // Fifteen seconds after the end, the loser is moored at the dock the rules choose, with 20 s of protection.
276	    const { respawnAt } = guest.status()!;
277	    await guest.waitFor(() => guest.ship() !== undefined, 20_000);
278	    const expected = rules.modes.ship.rules.respawnPoint({
279	      encounter: { x: Math.floor((at.host.x + at.guest.x) / 2), y: Math.floor((at.host.y + at.guest.y) / 2) },
280	      own: at.guest,
281	      opponents: [host.ship()!],
282	      clearRadius: rules.respawnClearRadius,
283	    });
284	    expect(guest.ship()).toMatchObject({ x: expected.x, y: expected.y, dock: expected.dockId, speed: 0 });
285	    expect(guest.status()).toMatchObject({ mode: "sea", protection: "respawn", protectedUntil: respawnAt + encounterRules.respawnProtectionTicks });
286	    expect(host.status()).toMatchObject({ protection: "", protectedUntil: 0 });
287	  }, 45_000);
288	
289	});
290	
291	const LEFT = duelInput("left");
292	const hold = (frames: number, bits = 0) => Array.from({ length: frames }, () => bits);
293	const seatConnected = (host: HeadlessClient, slot: number) => [...(host.fighter.lobby?.seats ?? [])].find((seat) => seat.slot === slot)?.connected;
294	
295	/** A duel at sea with the guest (and, if asked, the host) behind its own proxy, fighting for three seconds. */
296	async function fightBehindProxies(track: (client: HeadlessClient) => void, both = false) {
297	  const [hostProxy, guestProxy] = await Promise.all([ImpairmentProxy.start(server.port), ImpairmentProxy.start(server.port)]);
298	  const { host, guest } = await pairInRange(endpoint, track, { endpoints: [both ? hostProxy.endpoint : endpoint, guestProxy.endpoint] });
299	  // The guest walks towards the host all the time, so its held input is left.
300	  guest.fighter.play(() => LEFT);
301	  await grapple(host, guest);
302	  await host.waitFor(() => host.fighter.phase === "fighting", 5000);
303	  // The SDK reconnects only a room joined at least five seconds ago.
304	  await host.fighter.waitForConfirmed(180);
305	  return { host, guest, hostProxy, guestProxy, close: () => Promise.all([hostProxy.close(), guestProxy.close()]) };
306	}
307	
308	describe.concurrent("a fighter who drops (§12)", () => {
309	  it("gets neutral input after the held-input timeout, and resumes the same fight on reconnecting within ten seconds", async ({ onTestFinished }) => {
310	    const track = tracker(onTestFinished);
311	    const { host, guest, guestProxy, close } = await fightBehindProxies(track);
312	    onTestFinished(async () => void (await close()));
313	    const room = roomOf(host);
314	    const dropFrame = room.seaDuelDiagnostics(host.sessionId)!.frame;
315	    guestProxy.sever({ refuse: true });
316	    await host.waitFor(() => seatConnected(host, 1) === false, 5000);
317	    // While the guest is away the server substitutes: its held input (left) for 15 frames, then neutral.
318	    await host.fighter.waitForConfirmed(dropFrame + 50);
319	    const during = [...appliedPairs(host.fighter.bundles).entries()].filter(([frame]) => frame > dropFrame && frame <= dropFrame + 50);
320	    const substituted = during.filter(([, entry]) => entry.substituted[1]).map(([, entry]) => entry.pair[1]);
321	    expect(substituted.slice(0, INPUT_HOLD_FRAMES)).toEqual(hold(INPUT_HOLD_FRAMES, LEFT));
322	    expect(substituted.slice(INPUT_HOLD_FRAMES).length).toBeGreaterThan(0);
323	    expect(substituted.slice(INPUT_HOLD_FRAMES).every((bits) => bits === 0)).toBe(true);
324	    await sleep(500);
325	    guestProxy.restore();
326	    // The SDK reconnects on its own through the same address, within the ten seconds, into the same fight.
327	    await guest.waitFor(() => guest.fighter.connected && seatConnected(host, 1) === true, 9000);
328	    const back = room.seaDuelDiagnostics(host.sessionId)!.frame;
329	    await guest.fighter.waitForConfirmed(back + 60);
330	    expect(lobbyOf(host)?.phase).toBe("fighting");
331	    expect(guest.fighter.stats!.snapshotRestores).toBeGreaterThanOrEqual(1);
332	    expect(guest.fighter.stats!.desyncs).toBe(0);
333	    const duel = room.seaDuelDiagnostics(guest.sessionId)!;
334	    const frame = guest.fighter.duel!.rollback.confirmedFrame;
335	    const replayed = await replayRecordedDuel({ ...duel.inputLog, inputs: duel.inputLog.inputs.slice(0, frame) }, { seed: duel.seed });
336	    expect(hashState(guest.fighter.duel!.confirmedState)).toBe(replayed.hash);
337	    // Its own input counts again, and it is still in the match.
338	    const pairs = appliedPairs(host.fighter.bundles);
339	    expect([...pairs.entries()].some(([f, entry]) => f > back + 10 && !entry.substituted[1] && entry.pair[1] === LEFT)).toBe(true);
340	    expect(guest.status()?.mode).toBe("duel");
341	    expect(host.playerCount).toBe(2);
342	  }, 40_000);
343	
344	  it("forfeits after ten seconds absent, and leaves the match", async ({ onTestFinished }) => {
345	    const track = tracker(onTestFinished);
346	    const { host, guestProxy, close } = await fightBehindProxies(track);
347	    onTestFinished(async () => void (await close()));
348	    guestProxy.sever({ refuse: true });
349	    const droppedAt = Date.now();
350	    await host.waitFor(() => host.fighter.phase === "over", 15_000);
351	    expect(Date.now() - droppedAt).toBeGreaterThanOrEqual(9500);
352	    expect(lobbyOf(host)).toEqual({ phase: "over", winner: 0, reason: "forfeit" });
353	    await host.waitFor(() => host.status()?.protection === "win", 2000);
354	    await host.waitFor(() => host.playerCount === 1, 2000);
355	  }, 40_000);
356	
357	  it("forfeits at once when the fighter quits", async ({ onTestFinished }) => {
358	    const track = tracker(onTestFinished);
359	    const { host, guest } = await pairInRange(endpoint, track);
360	    await grapple(host, guest);
361	    await host.waitFor(() => host.fighter.phase === "fighting", 5000);
362	    const quitAt = Date.now();
363	    await guest.leave();
364	    await host.waitFor(() => host.fighter.phase === "over", 2000);
365	    expect(Date.now() - quitAt).toBeLessThan(1000);
366	    expect(lobbyOf(host)).toEqual({ phase: "over", winner: 0, reason: "forfeit" });
367	    await host.waitFor(() => host.status()?.protection === "win", 2000);
368	  });
369	
370	  it("cancels the duel when both fighters are gone on the same frame, in whichever order they are processed", async ({ onTestFinished }) => {
371	    const track = tracker(onTestFinished);
372	    const both = async (order: readonly [0, 1] | readonly [1, 0]) => {
373	      const { host, guest, hostProxy, guestProxy, close } = await fightBehindProxies(track, true);
374	      onTestFinished(async () => void (await close()));
375	      const room = roomOf(host);
376	      const byIndex = [host, guest].map((client) => room.clients.get(client.sessionId)!);
377	      // One network outage takes both fighters down at once.
378	      hostProxy.sever({ refuse: true });
379	      guestProxy.sever({ refuse: true });
380	      await host.waitFor(() => room.clients.length === 0, 5000);
381	      // Both reconnection windows run out between two frames: Colyseus calls the room's onLeave for each, one after
382	      // the other, in some order. Neither call decides anything by itself.
383	      for (const index of order) room.onLeave(byIndex[index]!);
384	      expect(room.seaDuelDiagnostics(host.sessionId)!.phase).toBe("fighting");
385	      await host.waitFor(() => room.seaDuelDiagnostics(host.sessionId)?.phase === "over", 1000);
386	      const outcome = room.seaDuelDiagnostics(host.sessionId)!.outcome;
387	      // The rules got a cancellation: no winner, no loser waiting to respawn, both returned as from a draw.
388	      await host.waitFor(() => room.encounterState.duels.length === 0, 1000);
389	      const records = room.encounterState.players.filter((player) => player.id === host.sessionId || player.id === guest.sessionId);
390	      expect(room.refusedDuelReports).toBe(0);
391	      return { outcome, returns: records.map((player) => [player.protection?.source, player.respawn]) };
392	    };
393	    const results = await Promise.all([both([0, 1]), both([1, 0])]);
394	    for (const result of results) {
395	      expect(result.outcome).toMatchObject({ winner: null, reason: "forfeit" });
396	      expect(result.returns).toEqual([
397	        ["draw", null],
398	        ["draw", null],
399	      ]);
400	    }
401	  }, 40_000);
402	});
