1	import { afterAll, beforeAll, describe, expect, it } from "vitest";
2	import { startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
3	import { createEncounterConfig, encounterRules } from "@pirate-sea-race/simulation/encounters";
4	import { ImpairmentProxy, logFromBundles, replayRecordedDuel, type HeadlessClient, type Impairment } from "@pirate-sea-race/test-tools";
5	import { attacker, defender, expectWithinBudget, opponentChanges, PLAY_FRAMES, SETTLE_FRAMES, type ScenarioReport } from "./harness.js";
6	import { brawler, grapple, pairInRange, resultOf, roomOf, tracker } from "./seaDuelSetup.js";
7	
8	/**
9	 * The impairment harness (`harness.ts`) on a duel inside a match room (§14): two players join a match through their
10	 * own impaired proxies, one grapples the other, and they fight the harness's scripted duel over the match room's
11	 * socket, with the same budget as the standalone duel room. The draw's return is here too: its mirrored fight needs
12	 * both fighters' inputs on time, so it runs alone rather than beside the other duels at sea.
13	 */
14	let server: RunningGameServer;
15	let endpoint: string;
16	const rules = createEncounterConfig();
17	
18	beforeAll(async () => {
19	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false, testPlacement: true });
20	  endpoint = `http://127.0.0.1:${server.port}`;
21	});
22	
23	afterAll(async () => {
24	  await server.close();
25	});
26	
27	async function runScenario(scenario: string, impairment: Impairment, seed: number): Promise<ScenarioReport> {
28	  const proxies = await Promise.all([ImpairmentProxy.start(server.port, impairment, seed), ImpairmentProxy.start(server.port, impairment, seed + 1)]);
29	  const joined: HeadlessClient[] = [];
30	  try {
31	    const { host, guest } = await pairInRange(endpoint, (client) => void joined.push(client), { endpoints: proxies.map((proxy) => proxy.endpoint) });
32	    host.fighter.play((frame) => (frame <= PLAY_FRAMES ? attacker(frame, host.fighter.duel!) : 0));
33	    guest.fighter.play((frame) => (frame <= PLAY_FRAMES ? defender(frame, guest.fighter.duel!) : 0));
34	    await grapple(host, guest);
35	    await host.waitFor(() => host.fighter.phase === "fighting", 8000);
36	    const players = [host.fighter, guest.fighter] as const;
37	    for (const player of players) await player.waitForConfirmed(PLAY_FRAMES + SETTLE_FRAMES, 30_000);
38	    const duel = roomOf(host).seaDuelDiagnostics(host.sessionId)!;
39	
40	    // Determinism on top of the live hash checks: the pairs each client received replay to the server's state.
41	    for (const player of players) {
42	      const log = logFromBundles(player.bundles);
43	      const replayed = await replayRecordedDuel(log, { seed: duel.seed });
44	      const fromServer = await replayRecordedDuel({ ...duel.inputLog, inputs: duel.inputLog.inputs.slice(0, log.inputs.length) }, { seed: duel.seed });
45	      expect(log.inputs.length).toBeGreaterThanOrEqual(PLAY_FRAMES + SETTLE_FRAMES);
46	      expect(replayed.hash).toBe(fromServer.hash);
47	    }
48	    const through = PLAY_FRAMES + SETTLE_FRAMES;
49	    const pair = <T>(pick: (player: (typeof players)[number], index: 0 | 1) => T): [T, T] => [pick(players[0], 0), pick(players[1], 1)];
50	    return {
51	      scenario,
52	      inputDelay: duel.inputDelay,
53	      corrections: pair((player) => player.stats!.corrections),
54	      correctionBound: pair((player, index) => opponentChanges(player, through) + player.stats!.substitutedFrames[index]),
55	      substituted: [duel.authority.repeated[0] + duel.authority.neutral[0], duel.authority.repeated[1] + duel.authority.neutral[1]],
56	      hashChecks: pair((player) => player.stats!.hashChecks),
57	      desyncs: pair((player) => player.stats!.desyncs),
58	      deepestReplay: pair((player) => player.stats!.deepestReplay),
59	      rateLimited: [duel.dropped["0"]!["rate-limited"], duel.dropped["1"]!["rate-limited"]],
60	      lostMessages: proxies[0].stats.lost[0] + proxies[0].stats.lost[1] + proxies[1].stats.lost[0] + proxies[1].stats.lost[1],
61	    };
62	  } finally {
63	    await Promise.all(joined.map((client) => client.leave()));
64	    await Promise.all(proxies.map((proxy) => proxy.close()));
65	  }
66	}
67	
