+  const sailing = () => {
+    let state = addShip(config, createMatchState(7), "a");
+    state = placeShip(config, state, "a", { ...config.map.hub, heading: 0 });
+    for (let frame = 0; frame < 30; frame++) state = step(config, state, { a: { buttons: 0, moveX: 0, moveY: -AXIS_SCALE } });
