+  };
+
+  it("keeps the grapple button apart from interact, and sailing ignores it", () => {
+    expect(GRAPPLE_BUTTON & INTERACT_BUTTON).toBe(0);
+    const state = sailing();
+    const ship = state.ships[0]!;
+    const input = { buttons: 0, moveX: 0, moveY: -AXIS_SCALE };
