+    expect(returnShip(config, state, "a", { ...open, dock: NOT_DOCKED }).ships[0]).toMatchObject({ ...open, speed: 0, dock: NOT_DOCKED });
+    const landIndex = config.map.terrain.findIndex((_, index) => terrainAt(config.map, index % config.map.widthTiles, Math.floor(index / config.map.widthTiles)) === Terrain.Land);
+    const inland = tileCentre(config, landIndex % config.map.widthTiles, Math.floor(landIndex / config.map.widthTiles));
+    expect(() => returnShip(config, state, "a", { ...inland, dock: NOT_DOCKED })).toThrow(RangeError);
+    expect(() => returnShip(config, state, "a", { ...open, dock: 999 })).toThrow(RangeError);
+    expect(() => returnShip(config, state, "a", { x: open.x + 0.5, y: open.y, dock: NOT_DOCKED })).toThrow(RangeError);
