+    expect(pointInSight(config, viewer, { x: viewer.x + config.sightRadius + 1, y: viewer.y })).toBe(false);
+    const diagonal = Math.floor(config.sightRadius / Math.SQRT2);
+    expect(pointInSight(config, viewer, { x: viewer.x + diagonal, y: viewer.y - diagonal })).toBe(true);
+  });
